// out_tu.cpp - GENERATED by the driver from captured bytes + oracle values
#include <bit>
#include <array>
struct Version { int major, minor, patch; std::array<char,16> tag; std::size_t tag_len; };

// bytes from __kairo_raw:
constexpr Version V = std::bit_cast<Version>(
    std::array<unsigned char, 40>{ 0x04,0,0,0, 0x08,0,0,0, /* ... */ });

// oracle values from __kairo_dump, baked in as literals:
static_assert(V.major == 4);
static_assert(V.minor == 8);
static_assert(V.patch == 1);
static_assert(V.tag_len == 4);
static_assert(V.tag[0]=='b' && V.tag[3]=='a');

// property 3: prove it's a genuine constant expression, not runtime-degraded
constexpr int probe[V.tag_len] = {};        // array bound needs a constant
static_assert(sizeof(probe)/sizeof(int) == 4);

